#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, l;
    cin >> n >> k >> l;
    const long long mod = 998244353;

    vector<long long> fac(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        fac[i] = (fac[i - 1] * i) % mod;
    }

    int size = 2 * n + 1;
    vector<vector<long long>> dp(size, vector<long long>(size + 1, 0));
    dp[0][0] = 1;

    for (int i = 1; i <= 2 * n; i++) {
        for (int j = 0; j <= i; j++) {
            if (j > 0) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % mod;
            }
            if (j + 1 <= size) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1] * (j + 1) % mod) % mod;
            }
        }
    }

    auto powMod = [&](long long base, int exp) -> long long {
        long long result = 1;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    };

    long long ans = 0;
    for (int i = k; i <= 2 * n; i++) {
        for (int j = k; j <= n; j++) {
            long long term = (dp[i][j] * dp[2 * n - i][j]) % mod;
            term = (term * fac[j]) % mod;
            ans = (ans + term) % mod;
        }
    }

    long long inv1 = powMod(dp[2 * n][0], mod - 2);
    long long inv2 = powMod(2 * n + 1, mod - 2);
    long long result = (l % mod) * ans % mod * inv1 % mod * inv2 % mod;
    cout << result << "\n";

    return 0;
}
